import 'package:flutter/material.dart';
import '../models/order_model.dart';
class OrderTrackingScreen extends StatelessWidget { final OrderModel order; const OrderTrackingScreen({super.key,required this.order}); static const statuses=['placed','confirmed','packed','out_for_delivery','delivered']; @override Widget build(BuildContext c){final current=statuses.indexOf(order.status);return Scaffold(appBar:AppBar(title:Text('Order #${order.id.substring(0,6).toUpperCase()}')),body:ListView(padding:const EdgeInsets.all(24),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Delivery status',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(order.estimatedDelivery==null?'Estimated delivery: soon':'Estimated delivery: ${order.estimatedDelivery!.hour.toString().padLeft(2,'0')}:${order.estimatedDelivery!.minute.toString().padLeft(2,'0')}')]))),const SizedBox(height:20),...List.generate(statuses.length,(i){final active=i<=current;return ListTile(leading:CircleAvatar(backgroundColor:active?Colors.green:Colors.grey.shade300,child:Icon(active?Icons.check:Icons.circle_outlined,color:active?Colors.white:Colors.grey)),title:Text(statuses[i].replaceAll('_',' ').toUpperCase(),style:TextStyle(fontWeight:active?FontWeight.bold:FontWeight.normal)),subtitle:i==current?const Text('Current status'):null);}),if(order.status=='out_for_delivery')Container(height:180,color:Colors.green.shade50,child:const Center(child:Icon(Icons.map,size:80,color:Colors.green))) ]);}}
